def data(n: int, p: int, nc: int):
    X = np.zeros((n, p)); y = np.zeros(n, dtype=int)
    for i in range(n):
        y[i] = i % nc
        for j in range(p):
            v = (i * 7919 + j * 104729 + i * j * 13 + j * j * 3) % 101
            X[i, j] = (v - 50.0) / 25.0 + (0.8 * y[i] if (j + y[i]) % 2 == 0 else -0.3 * y[i])
    return X, y

def close(name: str, got, exp: List[float], rtol: float = 1e-6, atol: float = 1e-8):
    g = np.asarray(got, dtype=float).ravel()
    if g.size != len(exp):
        print("TEST FAILED", name, "size", g.size, len(exp))
        return
    for i in range(len(exp)):
        if abs(g[i] - exp[i]) > atol + rtol * abs(exp[i]):
            print("TEST FAILED", name, "at", i, g[i], exp[i])
            return

def closes(name: str, got, exp, rtol: float = 1e-6, atol: float = 1e-8):
    close(name, [float(got)], [float(exp)], rtol, atol)

